RECORDS = [('细胞适应：肥大、增生、萎缩与化生', '细胞与组织变化', '细胞和组织的适应与损伤主题', '细胞可通过体积、数量或分化表型改变适应环境。肥大指细胞体积增大，增生指细胞数量增加；化生涉及一种成熟细胞类型被另一种成熟类型取代，适应不等于恶性肿瘤。', ['能区分四类基本适应改变。', '能避免把化生直接等同于癌。'], Q('组织因单个细胞体积增大而增大的变化叫什么？', '肥大', ['增生', '化生', '萎缩'], '肥大强调细胞体积，增生强调细胞数量；两者可在同一器官并存。'), Q('某组织的一类成熟上皮被另一类成熟上皮取代，应首先归入哪种形态学变化？', '化生', ['单纯肥大', '细胞数量减少意义的萎缩', '仅凭此即可确诊恶性肿瘤'], '化生是成熟细胞表型的替换；与肿瘤发生的关系需额外证据，不可直接画等号。')), ('可逆损伤、坏死与凋亡', '细胞与组织变化', '细胞和组织损伤；细胞死亡主题', '损伤的结局取决于强度、持续时间和细胞状态。坏死常伴膜完整性丧失和炎症；经典凋亡以细胞收缩、染色质变化和有序清除为特点，细胞死亡还包括其他调控机制。', ['能区分可逆损伤与死亡结局。', '能比较经典坏死与凋亡的主要形态。'], Q('经典细胞坏死过程中，哪项变化较为典型？', '膜完整性破坏并可引起周围炎症', ['细胞收缩并形成由膜包裹的凋亡小体', '单纯细胞体积增加而功能负荷相应增强', '成熟细胞表型被另一成熟类型替换'], '坏死常伴膜破坏与内容物外泄，可能引发炎症；不同死亡机制还可存在交叉。'), Q('观察到单个细胞收缩、染色质凝集和凋亡小体形成，周围炎症不明显，最符合哪个经典模式？', '凋亡', ['单纯细胞肥大', '典型液化性坏死的全部特征', '成熟细胞的化生'], '这些是经典凋亡形态特征；不能据单一现象解释所有细胞死亡形式。'), [(1, '先区分适应与损伤结局，避免把细胞变化一概当坏死')]), ('再生、肉芽组织与瘢痕修复', '组织修复', '损伤的修复主题', '组织修复可由残存细胞再生和纤维性修复共同完成。肉芽组织含新生毛细血管及成纤维细胞等，随后可重塑为瘢痕；修复结果受组织再生能力及支架完整性影响。', ['能区分再生与纤维性修复。', '能区分肉芽组织与肉芽肿。'], Q('创伤修复早期富含新生毛细血管和成纤维细胞的组织叫什么？', '肉芽组织', ['肉芽肿', '成熟瘢痕', '血栓机化后的致密纤维结节'], '肉芽组织是修复过程中的新生组织，名称与肉芽肿相近但概念不同。'), Q('同样面积的损伤中，若组织支架被严重破坏且细胞再生能力有限，通常更容易出现什么？', '较多纤维性修复和瘢痕形成', ['主要依靠原细胞完整再生且不形成瘢痕', '只出现细胞肥大即可完全替代缺损', '不需要新生血管或基质参与就能恢复原结构'], '支架和再生能力不足时，纤维性修复往往占较大比例；具体结果取决于组织和损伤条件。'), [(2, '修复方式需结合损伤范围和细胞存活状态')]), ('充血、淤血与局部循环改变', '循环障碍', '局部血液循环障碍主题', '充血常因动脉血输入增加，淤血通常因静脉回流受阻。二者都可增加局部血量，但机制和组织氧供后果不同；持续淤血可伴缺氧及组织改变。', ['能区分血流输入增加与回流受阻。', '能联系持续淤血与组织损伤。'], Q('因静脉回流受阻而出现的局部血液积聚，主要称为什么？', '淤血', ['动脉性充血', '局部缺血', '出血'], '淤血属于被动性血液积聚，与动脉流入增加导致的充血不同。'), Q('为何不能把慢性淤血理解为“血量多，所以组织供氧一定更好”？', '血液滞留与有效流动不足可同时存在，组织仍可能缺氧', ['局部血量越多就必然有越高的有效血流量', '只要静脉内有血，动脉供血条件就不再重要', '组织供氧仅由血管内总血量决定而不受流速影响'], '供氧依赖有效灌注和氧输送，血量增多并不能保证血液更新及氧供充足。'), [('med_physiology_007', '血流、压力与阻力关系有助于区分血量和有效灌注', 'soft')]), ('血栓、栓塞与梗死', '循环障碍', '局部血液循环障碍主题', '血栓是在活体心脏或血管内，由血液成分凝固、聚集等形成的固体质块；栓塞指不溶性物质随血流阻塞远处血管，栓子可有不同来源。梗死是局部供血障碍引起的缺血性坏死，三者相关但不等同。', ['能区分原位血栓和远处栓塞。', '能解释梗死与供血障碍的联系。'], Q('血栓片段脱落，随血流到远处阻塞血管，这一过程叫什么？', '血栓栓塞', ['原位血栓形成而无脱落', '血栓机化', '血栓再通'], '栓塞强调物质随血流移动并阻塞远处血管；来源是血栓时称血栓栓塞。'), Q('下列关于梗死的表述哪项最准确？', '局部供血障碍造成的缺血性坏死', ['单纯局部淤血，尚未发生组织坏死', '任何血栓形成的完全同义词', '仅由机械损伤形成的组织缺口'], '血管阻塞是否造成梗死，还受侧支循环、组织耐受性及阻塞程度等影响。'), [(2, '梗死的组织结局属于坏死'), (4, '循环障碍为血栓和缺血性损伤提供背景')]), ('水肿与体液分布的形态联系', '循环障碍', '局部血液循环障碍与水肿主题', '水肿是组织间隙或体腔液体过多的表现，可与静水压、血浆胶体渗透压、通透性和淋巴回流改变有关。局部肿胀还可有其他原因，不能只凭外观确定机制。', ['能列举水肿形成的不同机制。', '能区分形态表现与病因判断。'], Q('血浆蛋白明显减少可通过哪种机制促进组织间液增加？', '血浆胶体渗透压下降', ['血浆胶体渗透压升高', '毛细血管通透性必然降低', '淋巴回流量增大到完全抵消滤出的程度'], '血浆胶体渗透作用减弱可改变跨微血管液体交换，有利于液体在间质积聚。'), Q('若局部淋巴回流受阻而出现水肿，最直接受影响的环节是什么？', '组织间液及蛋白等回流能力下降', ['肾脏对钠水的重吸收直接增加', '局部毛细血管静水压因动脉入流增加而升高', '全身血浆胶体渗透压降低'], '淋巴系统负责回输部分间质液和蛋白，受阻可使局部液体积聚。'), [('med_anatomy_010', '淋巴回流结构是理解回流障碍性水肿的基础', 'soft')]), ('急性炎症的血管与细胞反应', '炎症', '炎症主题', '炎症是活体组织对损伤等刺激的防御反应，可伴组织损伤。急性炎症常涉及血管变化、通透性改变和白细胞募集，反应模式受刺激性质与时间影响。', ['能区分血管反应与白细胞募集。', '能解释炎症的防御与损伤两面性。'], Q('白细胞由血管内向损伤部位定向移动所依赖的重要过程是什么？', '趋化', ['单纯随机游走而无梯度方向', '成熟细胞的化生', '凝血因子的级联活化'], '趋化指细胞沿化学信号梯度定向运动，是炎症细胞募集过程的一部分。'), Q('急性炎症中，微血管通透性升高会直接促进什么？', '血浆蛋白和液体进入局部组织', ['蛋白及液体都被更严格限制在血管内', '只改变红细胞大小而不影响液体交换', '组织间液被单向全部抽回血管'], '通透性改变有利于渗出，与局部肿胀和效应分子到达有关，但具体反应依情境而变。'), [(6, '液体交换原理有助于理解炎性渗出')]), ('慢性炎症与肉芽肿', '炎症', '炎症主题', '慢性炎症可伴持续细胞浸润、组织损伤和修复。肉芽肿是以活化巨噬细胞等构成的特定组织反应模式，可由不同原因形成，不能仅凭肉芽肿一词确定某种感染。', ['能比较急性与慢性炎症的典型特点。', '能区分肉芽肿与肉芽组织。'], Q('肉芽肿这一反应模式的核心细胞成分通常与哪类细胞有关？', '活化巨噬细胞及其衍生细胞', ['主要由成纤维细胞与新生毛细血管组成', '主要由血小板与纤维蛋白组成', '主要由增生的腺上皮细胞组成'], '肉芽肿常由上皮样细胞、巨细胞等活化巨噬细胞相关成分构成，并可伴其他细胞。'), Q('病理描述出现“肉芽肿性炎症”时，最严谨的推论是什么？', '说明一种组织反应模式，病因仍需结合形态和其他证据', ['已唯一确定某一种感染病原', '等同于伤口早期肉芽组织', '必然属于恶性肿瘤'], '多种感染性或非感染性原因可产生肉芽肿，反应模式不等于唯一病因。'), [(7, '慢性炎症需与急性反应及持续刺激联系理解'), (3, '名称相近但肉芽组织与肉芽肿机制不同', 'soft')]), ('肿瘤异型性、浸润与转移', '肿瘤基础', '肿瘤主题', '肿瘤的生物学行为需结合细胞和组织异型性、生长方式及其他特征评估。恶性肿瘤可侵袭周围结构并发生转移；良恶性的判断不能仅靠体积或生长速度一个指标。', ['能区分浸润与转移。', '能说明肿瘤行为评估需要多种特征。'], Q('肿瘤细胞离开原发部位并在不连续的远处形成同源病灶，称为什么？', '转移', ['局部膨胀性生长', '沿邻近组织连续直接浸润', '原发灶内细胞增生'], '转移指形成与原发灶不连续的继发肿瘤病灶，与局部直接浸润不同。'), Q('为什么不能只凭肿块直径判断良性或恶性？', '大小与行为并非一一对应，还需组织学和侵袭等证据', ['所有小肿块都一定良性', '所有大肿块都一定恶性', '肿块大小足以代替全部病理检查'], '肿瘤体积受生长时间、位置和类型等影响，良恶性需综合相关特征。'), [(1, '先区分适应性增生与肿瘤性生长', 'soft')]), ('肿瘤分级与分期', '肿瘤基础', '肿瘤主题', '肿瘤分级通常反映分化、增殖等组织学特征，分期通常反映病变范围及扩散程度。具体系统因肿瘤类型而异，不能将级别和期别当作同一概念。', ['能区分组织学分级与解剖学分期。', '能说明不同肿瘤使用的评估系统有差异。'], Q('描述肿瘤原发范围、区域淋巴结及远处转移等信息，主要属于什么？', '分期', ['组织学分级', '细胞分化程度评价', '核异型性评分'], '分期描述病变范围；常见TNM系统按原发肿瘤、区域淋巴结及远处转移组织信息。'), Q('两个同类肿瘤组织学分级相同，但一个局限、另一个已有远处转移，哪种判断合理？', '两者可具有不同分期', ['分级相同必然分期相同', '分期只由细胞核大小决定', '有远处转移会使所有组织学特征自动相同'], '分级和分期描述不同维度，因此同级肿瘤可以处于不同阶段。'), [(9, '肿瘤浸润和转移是理解分期的基础')]), ('器官病变的结构与功能联系', '系统病理学习', '器官系统疾病各论主题', '系统病理将基本病变放入器官结构中分析。相同的炎症、坏死或纤维化因位置和范围不同，可造成不同功能后果；形态学与功能指标应相互补充。', ['能把基本病变与器官结构联系。', '能区分病变存在和功能损害程度。'], Q('肺泡壁广泛增厚而其他条件相近时，首先可能妨碍哪种过程？', '气体跨屏障扩散', ['气道内空气的对流输送本身', '血红蛋白与氧的固有结合常数', '呼吸中枢发出神经信号的全部过程'], '交换屏障增厚可延长扩散距离；实际气体交换还受面积、灌注等影响。'), Q('同一种纤维化病变发生在不同器官，功能影响为何可能不同？', '器官的结构任务、受累位置和范围不同', ['纤维化在任何部位的后果都完全相同', '形态改变永远不会影响功能', '只要有纤维化就能推知所有器官指标'], '结构与功能的联系依赖器官环境，不能从一个形态词推出全部功能结果。'), [(3, '纤维性修复是多器官结构变化的共同基础'), ('med_histology_008', '肺泡结构提供扩散屏障的具体例子', 'soft')]), ('病理取材、形态与辅助技术', '病理证据', '病理诊断和研究技术；分子病理主题', '病理判断依赖取材、组织形态及必要的免疫组织化学、分子检测等证据。标记阳性与阴性均需考虑方法和组织背景，辅助检测不能脱离形态和取材质量机械解释。', ['能说明取材代表性的重要性。', '能区分标记物表达与完整疾病判断。'], Q('病理标本若未取到目标病灶，最直接的限制是什么？', '检测结果可能不能代表目标病变', ['可直接证明目标部位完全没有病变', '提高了标本对病变异质性的覆盖程度', '能让标记物检测自动补足所有取材遗漏'], '标本代表性是诊断证据的前提，未取到病变可导致结果不反映目标区域。'), Q('某免疫组织化学标记阳性，合理的使用方式是什么？', '结合表达部位、形态、对照和其他证据解释', ['只凭一个阳性标记决定全部分型和治疗', '忽略阴阳性对照及背景染色', '把任何阳性都视为同一种恶性肿瘤'], '标记物有其敏感性、特异性和表达背景，综合判断才能减少误判。'), [(9, '肿瘤形态知识有助于理解辅助技术的一个应用领域；取材和检测原则也适用于其他病变', 'soft'), ('med_biochem_012', '分子靶标检测的意义需要区分存在、表达和功能', 'soft')])]
